def is_reflexive(relation: set, A: set) -> bool:
    return all((a, a) in relation for a in A)

A = {1, 2, 3}
R = {(1, 1), (2, 2), (3, 3), (1, 2)}
print(is_reflexive(R, A))  # True, every element relates to itself

R2 = {(1, 1), (2, 2), (1, 2)}
print(is_reflexive(R2, A))  # False, (3, 3) is missing

def is_symmetric(relation: set) -> bool:
    return all((b, a) in relation for (a, b) in relation)

follows = {("alice", "bob"), ("bob", "alice"), ("carol", "bob")}
print(is_symmetric(follows))  # False, bob does not follow carol back

mutual_friends = {("alice", "bob"), ("bob", "alice")}
print(is_symmetric(mutual_friends))  # True

def is_transitive(relation: set) -> bool:
    for (a, b) in relation:
        for (b2, c) in relation:
            if b == b2 and (a, c) not in relation:
                return False
    return True

ancestor_of = {("grandpa", "dad"), ("dad", "me"), ("grandpa", "me")}
print(is_transitive(ancestor_of))  # True

friend_of = {("alice", "bob"), ("bob", "carol")}
print(is_transitive(friend_of))  # False, (alice, carol) is missing

def is_equivalence(relation: set, A: set) -> bool:
    return is_reflexive(relation, A) and is_symmetric(relation) and is_transitive(relation)

A = {1, 2, 3, 4}
same_parity = {(a, b) for a in A for b in A if a % 2 == b % 2}
print(is_equivalence(same_parity, A))  # True, "has the same parity as" is an equivalence relation

